// Neon Escape – minimal endless runner
// Canvas id="game" assumed in the surrounding HTML
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return; // abort if missing
  const ctx = canvas.getContext('2d');
  // fullscreen canvas
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  const player = {
    w: 40,
    h: 40,
    x: 80,
    y: canvas.height - 100,
    vy: 0,
    color: '#0ff', // neon cyan
    onGround: true,
  };
  const GRAVITY = 0.8;
  const JUMP = -15;
  const obstacles = [];
  let lastObstacle = 0;
  let score = 0;

  // input – tap/click to jump
  canvas.addEventListener('pointerdown', () => {
    if (player.onGround) {
      player.vy = JUMP;
      player.onGround = false;
    }
  });

  function spawnObstacle() {
    const size = Math.random() * 30 + 20; // 20‑50px width/height
    const gap = Math.random() * 200 + 150; // distance between obstacles
    obstacles.push({
      x: canvas.width + size,
      y: canvas.height - size - 60, // sits on ground line
      w: size,
      h: size,
      speed: 6,
    });
    lastObstacle = performance.now() + gap;
  }

  function update(dt) {
    // player physics
    player.vy += GRAVITY;
    player.y += player.vy;
    if (player.y + player.h >= canvas.height - 60) {
      player.y = canvas.height - 60 - player.h;
      player.vy = 0;
      player.onGround = true;
    }

    // obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= o.speed;
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }
    // spawn new obstacle if needed
    if (performance.now() > lastObstacle) spawnObstacle();

    // collision detection (AABB)
    for (const o of obstacles) {
      if (
        player.x < o.x + o.w &&
        player.x + player.w > o.x &&
        player.y < o.y + o.h &&
        player.y + player.h > o.y
      ) {
        // game over – stop animation
        cancelAnimationFrame(animId);
        alert('Game Over! Score: ' + Math.floor(score / 1000));
        return;
      }
    }

    score += dt;
  }

  function draw() {
    // clear with dark background
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // ground line
    ctx.strokeStyle = '#0ff';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(0, canvas.height - 60);
    ctx.lineTo(canvas.width, canvas.height - 60);
    ctx.stroke();

    // player – glowing square
    ctx.fillStyle = player.color;
    ctx.shadowColor = player.color;
    ctx.shadowBlur = 15;
    ctx.fillRect(player.x, player.y, player.w, player.h);
    ctx.shadowBlur = 0;

    // obstacles – neon bars
    ctx.fillStyle = '#f0f';
    ctx.shadowColor = '#f0f';
    ctx.shadowBlur = 12;
    for (const o of obstacles) {
      ctx.fillRect(o.x, o.y, o.w, o.h);
    }
    ctx.shadowBlur = 0;

    // score
    ctx.fillStyle = '#fff';
    ctx.font = '20px monospace';
    ctx.fillText('Score: ' + Math.floor(score / 1000), 20, 30);
  }

  let last = performance.now();
  let animId;
  function loop() {
    const now = performance.now();
    const dt = now - last;
    last = now;
    update(dt);
    draw();
    animId = requestAnimationFrame(loop);
  }

  // start loop
  spawnObstacle();
  loop();
})();
